/* Eingebaute Karten – direkt aus den Vorlesungsfolien.
   Jede Karte: [Vorderseite, Definition (wie auf der Folie), Einfach gesagt, Beispiel, Folie]
   Quelle = Thema-Quelle + Foliennummer. Beginnt die Foliennummer mit "=", ersetzt sie die Quelle ganz.
   Steht in der Quelle "Folie" oder "Seite", heißt der erste Abschnitt "Laut Folie", sonst "Bedeutung". */
const SUP={0:'⁰',1:'¹',2:'²',3:'³',4:'⁴',5:'⁵',6:'⁶',7:'⁷',8:'⁸',9:'⁹'};
const sup=n=>String(n).split('').map(d=>SUP[d]).join('');
const POT=[];
for(let i=0;i<=16;i++)POT.push(['2'+sup(i),String(2**i),
  i===0?`Alles hoch 0 ist 1.`:`Doppelt so viel wie 2${sup(i-1)} = ${2**(i-1)}.`,
  `Binär: 1${'0'.repeat(i)} (eine 1 und ${i} ${i===1?'Null':'Nullen'})`,'']);

